async def _build(hass: HomeAssistant, freezer) -> tuple[list[dict], dict[str, dict], dict[str, dict], dict]:
    freezer.move_to(f"{TODAY} 12:00:00")
    sums = {}
    for _title, _data, sensors, _options in CONTRACTS:
        for entity_id, (latest, offset, unit) in sensors.items():
            hass.states.async_set(entity_id, str(latest[1]), {"unit_of_measurement": unit})
            sums[entity_id] = (latest, offset)

    async def latest(_hass, entity_id):
        return sums[entity_id][0]

    async def offset(_hass, entity_id, _at):
        return sums[entity_id][1]

    async def average(*_args, **_kwargs):
        return None

    with (
        patch("custom_components.tariffy.coordinator._get_latest_sum", latest),
        patch("custom_components.tariffy.coordinator._get_historic_value", offset),
        patch("custom_components.tariffy.coordinator._get_average_price", average),
    ):
        for title, data, _sensors, options in CONTRACTS:
            entry = MockConfigEntry(domain=DOMAIN, title=title, data=data, options=options)
            entry.add_to_hass(hass)
            assert await hass.config_entries.async_setup(entry.entry_id)
        await hass.async_block_till_done()

    async def _notify(call):  # a notify service makes the "notification target" field appear
        return None

    hass.services.async_register("notify", "mobile_app_pixel", _notify)

    contracts = panel.async_contracts(hass)
    for index, contract in enumerate(contracts, start=1):
        contract["entry_id"] = f"contract-{index}"

    # The form of the options flow ("plan the next contract") exactly as Home
    # Assistant serialises it for its REST API, which is what the panel renders.
    class _Serialiser(FlowManagerResourceView):
        url = "/unused"
        name = "unused"

    serialiser = _Serialiser(hass.config_entries.options)
    config_serialiser = _Serialiser(hass.config_entries.flow)
    flows: dict[str, dict] = {}
    reconfigure: dict[str, dict] = {}
    for index, entry in enumerate(hass.config_entries.async_entries(DOMAIN), start=1):
        result = await hass.config_entries.options.async_init(entry.entry_id)
        form = serialiser._prepare_result_json(result)
        hass.config_entries.options.async_abort(result["flow_id"])
        form["flow_id"] = f"flow-{index}"
        form["handler"] = f"contract-{index}"
        flows[f"contract-{index}"] = form

        # The two steps of "Reconfigure": general data, then the data of the sparte. The
        # second form is what Home Assistant returns after the first one was sent unchanged.
        first = await hass.config_entries.flow.async_init(
            DOMAIN, context={"source": "reconfigure", "entry_id": entry.entry_id}
        )
        second = await hass.config_entries.flow.async_configure(
            first["flow_id"], _form_defaults(first)
        )
        steps = []
        for number, result in enumerate((first, second), start=1):
            form = config_serialiser._prepare_result_json(result)
            form["flow_id"] = f"rflow-{index}"
            form["handler"] = DOMAIN
            steps.append(form)
        hass.config_entries.flow.async_abort(first["flow_id"])
        reconfigure[f"contract-{index}"] = {"first": steps[0], "second": steps[1]}

    # "New contract": the first step (name and sparte), then the step the chosen sparte leads to.
    first = await hass.config_entries.flow.async_init(DOMAIN, context={"source": "user"})
    start = config_serialiser._prepare_result_json(first)
    start["flow_id"], start["handler"] = "cflow-1", DOMAIN
    hass.config_entries.flow.async_abort(first["flow_id"])
    steps: dict[str, dict] = {}
    for sparte in ("electricity", "electricity_ht_nt", "gas", "water", "internet"):
        result = await hass.config_entries.flow.async_init(DOMAIN, context={"source": "user"})
        values = {**_form_defaults(result), "name": "Neuer Vertrag", "sparte": sparte, "anbieter": "Anbieter"}
        result = await hass.config_entries.flow.async_configure(result["flow_id"], values)
        form = config_serialiser._prepare_result_json(result)
        form["flow_id"], form["handler"] = "cflow-1", DOMAIN
        hass.config_entries.flow.async_abort(result["flow_id"])
        steps[sparte] = form
    create = {"first": start, "steps": steps}
    return contracts, flows, reconfigure, create


async def test_panel_fixtures_match_the_backend(hass: HomeAssistant, freezer):
    contracts, flows, reconfigure, create = await _build(hass, freezer)
    document = {
        "today": TODAY, "contracts": contracts, "flows": flows, "reconfigure": reconfigure, "create": create,
    }
    text = json.dumps(document, indent=2, ensure_ascii=False, sort_keys=True) + "\n"

    if os.environ.get("UPDATE_FIXTURES"):
        FIXTURE.write_text(text, encoding="utf-8")
    assert FIXTURE.exists(), "run with UPDATE_FIXTURES=1 to create the fixture"
    assert FIXTURE.read_text(encoding="utf-8") == text, (
        "panel fixture is out of date, run: UPDATE_FIXTURES=1 pytest tests/test_panel_fixtures.py"
    )
    assert len(contracts) == len(CONTRACTS)
